import fs from 'node:fs';
import { Page } from '@playwright/test';
import { Api } from '../fixtures/api';
import { signIn } from '../fixtures/login';
import { expect, test } from '../fixtures/test';
import { unique } from '../fixtures/users';

/**
 * Reports are generated by the analytics service, stored in MinIO and downloaded from
 * there. Each test signs in as an admin of its own: generating reports is limited to a
 * few a minute per user, and a shared admin would use that up across tests and browsers.
 */
test('the admin generates and downloads a CSV report', async ({ api, page }) => {
  await signInAsNewAdmin(await api('admin'), page);

  const file = await generateAndDownload(page, 'Enrollment Summary');

  expect(file.name).toMatch(/\.csv$/);
  const header = file.content.toString('utf8').split(/\r?\n/)[0];
  expect(header).toContain('"Degree Program / Course"');
  expect(header).toContain('"Waitlisted"');
});

test('the admin generates and downloads a PDF report', async ({ api, page }) => {
  await signInAsNewAdmin(await api('admin'), page);

  const file = await generateAndDownload(page, 'Grade Distribution');

  expect(file.name).toMatch(/\.pdf$/);
  expect(file.content.subarray(0, 5).toString('latin1')).toBe('%PDF-');
});

async function signInAsNewAdmin(admin: Api, page: Page): Promise<void> {
  const account = {
    name: `Report Admin ${unique()}`,
    email: `e2e.report.admin.${unique().toLowerCase()}@ucms.test`,
    password: 'E2e-Report-Password-1!',
  };
  await admin.post('/api/identity/users', { ...account, role: 'ADMIN', status: 'ACTIVE' });
  await signIn(page, account);
}

async function generateAndDownload(page: Page, reportName: string): Promise<{ name: string; content: Buffer }> {
  await page.goto('/app/reports');
  const row = page.getByRole('row').filter({ hasText: reportName });

  await row.getByRole('button', { name: 'Generate' }).click();
  // The button reads "Generating…" while it runs, and "Generate" again when it is done.
  await expect(row.getByRole('button', { name: 'Generate', exact: true })).toBeEnabled();
  await expect(row.getByRole('button', { name: 'Download' })).toBeEnabled();

  const [download] = await Promise.all([
    page.waitForEvent('download'),
    row.getByRole('button', { name: 'Download' }).click(),
  ]);
  const content = fs.readFileSync(await download.path());
  expect(content.length).toBeGreaterThan(0);
  return { name: download.suggestedFilename(), content };
}
